#include "fa_kernel.h"
extern "C" __global__ __aicore__ void fa_custom_fp16(GM_ADDR q,GM_ADDR k,GM_ADDR v,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    FAKernel<half> kk; kk.Init(q,k,v,y,t,&p); kk.Process();
}
extern "C" void fa_do_fp16(uint32_t d,void* s,uint8_t* q,uint8_t* k,uint8_t* v,uint8_t* y,uint8_t* t){
    fa_custom_fp16<<<d,nullptr,s>>>(q,k,v,y,t);
}

