#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "fa_tiling.h"
extern "C" void fa_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace fa_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_flash_attention_score(const at::Tensor &q, const at::Tensor &k, const at::Tensor &v) {
    TORCH_CHECK(q.dim()==4&&k.dim()==4&&v.dim()==4,"[B,H,S,D]");
    TORCH_CHECK(q.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(q.is_contiguous()&&k.is_contiguous()&&v.is_contiguous(),"contiguous");
    const auto B=q.sizes()[0], Hq=q.sizes()[1], S=q.sizes()[2], D=q.sizes()[3];
    const auto Hk=k.sizes()[1], Skv=k.sizes()[2];
    const auto M=static_cast<int32_t>(B*Hq*S);
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty_like(q);
    at::Tensor tc=at::empty({sizeof(FAKernelTiling)},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<FAKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=static_cast<int32_t>(D); t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    t->Hq=static_cast<int32_t>(Hq); t->Hk=static_cast<int32_t>(Hk);
    t->S=static_cast<int32_t>(S); t->Skv=static_cast<int32_t>(Skv);
    t->invSqrtD=1.0f/sqrtf(static_cast<float>(D));
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    fa_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(q.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(k.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(v.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_fa_ext, m) { m.def("run_flash_attention_score",&fa_ext::run_flash_attention_score,""); }

