#pragma once
#include <cstdint>
#include "kernel_operator.h"
template <typename T>
__aicore__ inline void CopyTiling(T *t, GM_ADDR g) {
    int32_t *d = reinterpret_cast<int32_t *>(t);
    auto *s = reinterpret_cast<__gm__ int32_t *>(g);
    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) d[i] = s[i];
}

