#pragma once
#ifndef FA_TILING_H
#define FA_TILING_H
#include <cstdint>
constexpr int32_t DEFAULT_BLOCK_M = 128;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 32;
struct FAKernelTiling { int32_t M; int32_t N; int32_t blockM; int32_t usedCoreNum; int32_t tasksPerCore;
    int32_t Hq; int32_t Hk; int32_t S; int32_t Skv; float invSqrtD; };
#endif
